GET_NODE = '(echo "I am node`get_node_id`")'
UPTIME = '(echo "Current date: `date`")'
CUR_TIME = '(echo "Current uptime: `uptime`")'
SPACE_USAGE = '(echo "Current space usage: "; df -h)'
CONFIG_MODIFIED = (
    '(if [ "$(ls -la /run/coma/type/ | grep -v etc | grep -i mnt)" ];'
    ' then echo "Configuration is modified!";'
    " ls -la /run/coma/type | grep mnt;"
    ' else echo "configuration is not modified"; fi)'
)
PING_TOWER = (
    "(for i in $(seq 2 16) ; do"
    " if ping -c 1 -W 1 192.168.101.$i > /dev/null 2>&1;"
    " then"
    " if ssh -y -q -o BatchMode=yes -o StrictHostKeyChecking=no 192.168.101.$i exit;"
    ' then echo "Ping answer is OK and SSH is OK from host: 192.168.101.$i";'
    ' else echo "Ping answer is OK but NO answer via SSH from host: 192.168.101.$i"; continue;'
    " fi;"
    ' else echo "No ping answer from host: 192.168.101.$i";'
    " fi; done)"
)

SIMPLIFIED_PING_TOWER = (
    "(for i in $(seq 2 16); do"
    " if ping -c 1 -W 1 192.168.101.$i > /dev/null 2>&1;"
    ' then echo "Ping answer is OK from host: 192.168.101.$i";'
    ' else echo "No ping answer from host: 192.168.101.$i";'
    " fi; done)"
)

SYSCON_RUNNING = (
    '(if [ "$(ps 2>/dev/null | grep -i syscon | grep -v grep)" ] ||'
    ' [ "$(ps aux 2>/dev/null | grep -i syscon | grep -v grep)" ];'
    ' then echo "Syscon is available" ;'
    ' else echo "Syscon is NOT available"; systemctl --no-pager status syscon 2>/dev/null ; fi)'
)

CCS_RUNNING = (
    '(if [ "$(ps 2>/dev/null | grep -i ccs | grep -v grep)" ]||'
    ' [ "$(ps aux 2>/dev/null | grep -i ccs | grep -v grep)" ];'
    ' then echo "CCS is available" ; else echo "CCS is NOT available"; ps 2>/dev/null; ps aux 2>/dev/null ;'
    " systemctl --no-pager status ccs 2>/dev/null ; fi)"
)

LIST_UNITS = '(echo "systemd unit list: `systemctl list-units --type=service --no-pager 2>/dev/null`")'
UNIT_HWID = '(echo "Unit HWID: $(cat /run/coma/unit/hwid.txt)")'

DEBUG_COMMANDS = (
    GET_NODE,
    CUR_TIME,
    UPTIME,
    CCS_RUNNING,
    SPACE_USAGE,
    SYSCON_RUNNING,
    CONFIG_MODIFIED,
    UNIT_HWID,
    LIST_UNITS,
    PING_TOWER,
)

PS_AUX = '(echo "ps output: `ps aux 2>/dev/null` `ps 2>/dev/null` ")'
MESSAGES_OUTPUT = '(echo "Messages output:" ; cat /var/log/messages ; echo "")'
DMESG_OUTPUT = '(echo "dmesg: "; dmesg ; echo "")'
JOURNALCTL_OUTPUT = '(echo "journalctl last 200 lines: `journalctl -n 200 --no-pager 2>/dev/null`")'
AUTH_LOG = '(echo "Auth log: `head -200 /var/log/auth.log 2>/dev/null`")'
RUNTIME_TAIL_200_LINES = (
    '(echo "Last 200 lines of runtime:"; cat /var/log/runtime.log 2>/dev/null |'
    " tail -n 200 ; strings /var/log/aasyslog/runtime_DEFAULT.bin 2>/dev/null | tail -n 200)"
)

CCS_FAILURE_COMMANDS = (PS_AUX, MESSAGES_OUTPUT, DMESG_OUTPUT, JOURNALCTL_OUTPUT, AUTH_LOG, RUNTIME_TAIL_200_LINES)

SNAPSHOT_CMD = "ccsShell.sh log -a -c full -z {snapshot_name}"
CCS_FAILURE_MSG = "CCS Failure"
CCS_OK_MSG = "CCS OK"

CCS_RUNNING_CHECK = (
    'if [ "$(ps 2>/dev/null | grep -i ccs | grep -v grep)" ] ||'
    ' [ "$(ps aux 2>/dev/null | grep -i ccs | grep -v grep)" ];'
    ' then echo "{ccs_ok}" ; else echo "{ccs_nok_msg}" ; fi'
)

PING_CMD = "ping -c 1 -W 1 {ip}"
MASTER_SSH_WRAPPER = "ssh -q 192.168.100.1 '{cmd} ; exit' &"

FAULTS_CMD = "sed -n '/[Aa]ctive faults:/,/[Ii]n[Aa]ctive faults:/p' /run/fault_history_log_temp.txt | grep {option}"
GET_CRITICAL_FAULTS_CMD = FAULTS_CMD.format(option="-i critical")
GET_NORMAL_FAULTS_CMD = FAULTS_CMD.format(option='-Ev "critical|faults|=======|Severity"')
